import { PUBLIC_POCKETBASE_URL } from '$env/static/public';
import type { TypedPocketBase } from '$lib/types/pocketbase-types';
import PocketBase from 'pocketbase';
export const pocketbaseAdminClient = new PocketBase(PUBLIC_POCKETBASE_URL) as TypedPocketBase;
pocketbaseAdminClient.autoCancellation(false);
// the credentials can be filled via env variables
await pocketbaseAdminClient.admins.authWithPassword(SECRET_POCKETBASE_EMAIL, SECRET_POCKETBASE_PW, {
// This will trigger auto refresh or auto reauthentication in case
// the token has expired or is going to expire in the next 30 minutes.
autoRefreshThreshold: 30 * 60
});
