async function update() {
  const pb = new PocketBase('http://127.0.0.1:8090');
  await pb.collection('_superusers').authWithPassword('admin@example.com', 'adminpassword');

  const res = await pb.send('/api/collections/gallery', {});
  console.log('Before update:', JSON.stringify(res.fields, null, 2));

  const imageField = res.fields.find(f => f.name === 'image');
  if (imageField) {
    imageField.thumbs = ["100x100"];
  }

  const updated = await pb.send('/api/collections/gallery', {
    method: 'PATCH',
    body: JSON.stringify({
      fields: res.fields
    })
  });
  console.log('After update:', JSON.stringify(updated.fields, null, 2));
}

